from pathlib import Path
import yaml
P=Path('src/content/docs'); lang='en'; number=1

def t(en,lt):return lt if lang=='lt' else en

def block(kind,title,body,figure=None,mode=None):
 f=f' figure="{figure}" figureProps={{{{mode: "{mode}"}}}} alt="{t("Interactive ideal thermal model; the same values are listed in a data table.","Interaktyvus idealus šiluminis modelis; tos pačios reikšmės pateiktos duomenų lentelėje.")}"' if figure else ''
 return f'<Block kind="{kind}" title="{title}"{f}>\n\n{body}\n\n</Block>\n'

def frames(parts):return '<Frames>\n'+''.join(f'<Frame title="{title}">\n\n{body}\n\n</Frame>\n' for title,body in parts)+'</Frames>'

def hints(*texts):return '<Hints>\n'+''.join(f'<Hint>{h}</Hint>\n' for h in texts)+'</Hints>'

def choice(id,prompt,options,solution,outcome,tip=None,multi=False):
 s=f'<Choice id="g9-thermal-0{number}-{id}" outcome="{outcome}"'+(' multi' if multi else '')+'>\n\n'+prompt+'\n\n'
 for text,right,why in options:s+=f'<Option'+(' correct' if right else '')+f'>{text}<Why>{why}</Why></Option>\n'
 if tip:s+=hints(tip)+'\n'
 return s+f'<Solution>\n\n{solution}\n\n</Solution>\n</Choice>\n'

def numeric(id,prompt,answer,solution,outcome,wrong=None,tip=None,unit=None):
 s=f'<Numeric id="g9-thermal-0{number}-{id}" answer="{answer}" outcome="{outcome}"'+(f' unit="{unit}"' if unit else '')+'>\n\n'+prompt+'\n\n'
 for value,why in (wrong or []):s+=f'<Why value="{value}">{why}</Why>\n'
 if tip:s+=hints(tip)+'\n'
 return s+f'<Ok>{solution}</Ok>\n<Solution>\n\n{solution}\n\n</Solution>\n</Numeric>\n'

def quantity(id,prompt,expected,q,units,show,solution,outcome,wrong=None,tip=None,tolerance=.05):
 s=f'<Quantity id="g9-thermal-0{number}-{id}" expected={{{expected}}} quantity="{q}" units="{units}" show="{show}" tolerance={{{tolerance}}} outcome="{outcome}">\n\n{prompt}\n\n'
 for value,why in (wrong or []):s+=f'<Why value="{value}">{why}</Why>\n'
 if tip:s+=hints(tip)+'\n'
 return s+f'<Ok>{solution}</Ok>\n<Solution>\n\n{solution}\n\n</Solution>\n</Quantity>\n'

def example(title,steps,fade=0):return f'<Example title="{title}" fade={{{fade}}}>\n\n'+''.join(f'<ExStep>\n\n{s}\n\n</ExStep>\n' for s in steps)+'</Example>\n'

def turn(body):return '<YourTurn>\n\n'+body+'\n</YourTurn>\n'

def task(id,prompt,marks,solution,outcome):return f'<Task id="g9-thermal-0{number}-{id}" outcome="{outcome}">\n\n{prompt}\n\n<Marks>\n'+''.join(f'<Mark pts={{1}}>{m}</Mark>\n' for m in marks)+f'</Marks>\n<Solution>\n\n{solution}\n\n</Solution>\n</Task>\n'

